python3 <<'PY'
import json
for label, path in [("BARE","evidence/run-bare.jsonl"),
                    ("DRAFT","evidence/run-draft.jsonl"),
                    ("FIRES","evidence/run-fires.jsonl")]:
    print(f"\n========= {label} =========")
    turns=None; dur=None; cost=None
    for line in open(path):
        e=json.loads(line)
        t=e.get("type")
        if t=="assistant":
            for b in e.get("message",{}).get("content",[]):
                if b.get("type")=="text":
                    txt=b["text"].strip()
                    if txt: print(f"  TEXT: {txt[:400]}")
                elif b.get("type")=="tool_use":
                    inp=b.get("input",{})
                    keys={k:(str(v)[:120]) for k,v in inp.items() if k in ("file_path","command","pattern","old_string","new_string")}
                    print(f"  TOOL: {b['name']}  {keys}")
        elif t=="user":
            m=e.get("message",{})
            content=m.get("content",[]) if isinstance(m.get("content"),list) else []
            for b in content:
                if b.get("type")=="tool_result":
                    c=b.get("content","")
                    if isinstance(c,list):
                        c="\n".join(x.get("text","") for x in c if x.get("type")=="text")
                    err = " [ERROR]" if b.get("is_error") else ""
                    print(f"  RESULT{err}: {str(c)[:220]}")
        elif t=="result":
            turns=e.get("num_turns"); dur=e.get("duration_ms"); cost=e.get("total_cost_usd")
    if turns is not None:
        print(f"  ==> turns={turns} dur_ms={dur} cost=${cost}")
PY

